C["Presets"]=make("<div><section class=\"s_climb_kit climb-p1 pt40 pb40\"><div class=\"container\"><p class=\"climb-eyebrow\">Preset 1 White</p><h3 class=\"climb-statement climb-statement-sm\">Find your <span class=\"climb-accent\"><em>people</em></span></h3><p>Reading-heavy pages, forms and the release ladder. <a href=\"#\">A link in running text</a>.</p><p class=\"climb-ctas\"><a href=\"#\" class=\"btn btn-primary\">Get your ticket</a><a href=\"#\" class=\"btn btn-outline-secondary\">Partner with ClimbUK</a></p></div></section><section class=\"s_climb_kit climb-p2 pt40 pb40\"><div class=\"container\"><p class=\"climb-eyebrow\">Preset 2 Light Grey</p><h3 class=\"climb-statement climb-statement-sm\">Find your <span class=\"climb-accent\"><em>people</em></span></h3><p>A quiet change of pace between dark sections. <a href=\"#\">A link in running text</a>.</p><p class=\"climb-ctas\"><a href=\"#\" class=\"btn btn-primary\">Get your ticket</a><a href=\"#\" class=\"btn btn-outline-secondary\">Partner with ClimbUK</a></p></div></section><section class=\"s_climb_kit climb-p3 pt40 pb40\"><div class=\"container\"><p class=\"climb-eyebrow\">Preset 3 Dark Brown</p><h3 class=\"climb-statement climb-statement-sm\">Find your <span class=\"climb-accent\"><em>people</em></span></h3><p>The default ground. Dark first. <a href=\"#\">A link in running text</a>.</p><p class=\"climb-ctas\"><a href=\"#\" class=\"btn btn-primary\">Get your ticket</a><a href=\"#\" class=\"btn btn-outline-secondary\">Partner with ClimbUK</a></p></div></section><section class=\"s_climb_kit climb-p4 pt40 pb40\"><div class=\"container\"><p class=\"climb-eyebrow\">Preset 4 Climb Orange</p><h3 class=\"climb-statement climb-statement-sm\">Find your <span class=\"climb-accent\"><em>people</em></span></h3><p>Calls to action and the close. White text is large only. <a href=\"#\">A link in running text</a>.</p><p class=\"climb-ctas\"><a href=\"#\" class=\"btn btn-primary\">Get your ticket</a><a href=\"#\" class=\"btn btn-outline-secondary\">Partner with ClimbUK</a></p></div></section><section class=\"s_climb_kit climb-p5 pt40 pb40\"><div class=\"container\"><p class=\"climb-eyebrow\">Preset 5 Charcoal</p><h3 class=\"climb-statement climb-statement-sm\">Find your <span class=\"climb-accent\"><em>people</em></span></h3><p>Ticket and audience sections, the second dark ground. <a href=\"#\">A link in running text</a>.</p><p class=\"climb-ctas\"><a href=\"#\" class=\"btn btn-primary\">Get your ticket</a><a href=\"#\" class=\"btn btn-outline-secondary\">Partner with ClimbUK</a></p></div></section></div>",["Foundations", "The five grounds, each with its own text, link and button colours", "Presets"]);
C["Headline"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><p class=\"climb-eyebrow\">Climb27 / The Festival for Business Growth</p><h1 class=\"climb-display\">Your business. Bigger <span class=\"climb-accent\"><em>stage</em></span>.</h1><h2 class=\"climb-statement climb-ruled\">Not a <em>conference</em>. A <span class=\"climb-accent\">festival</span> for business growth.</h2><h3 class=\"climb-statement climb-statement-sm\">ClimbAwards: be the name behind the <em>moment</em></h3><p class=\"lead climb-lead\">Lead text: one or two sentences that say what happens, for whom, and what to do next.</p></div></section>",["Foundations", "Uppercase display lines with one orange word and one italic word", "Headline"]);
