C["Sticker"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"d-flex flex-wrap gap-5 align-items-center pt16 pb16\"><p class=\"climb-sticker\">VIP</p><p class=\"climb-sticker\">Climb27</p><p class=\"climb-sticker climb-sticker-dark\">#ClimbUK</p><div class=\"climb-photo\" style=\"max-width:320px\"><img src=\"/_blob/6fcf57fe970781e3591e3e814b24dda5\" class=\"img img-fluid\" alt=\"Guests at the drinks reception\"><p class=\"climb-sticker\">VIP</p></div></div></div></section>",["Festival devices", "Tilted stickers that pin to a card or photo corner", "Sticker"]);
