C["TicketCard"]=make("<div><section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"row g-5 align-items-start\"><div class=\"col-lg-6\"><div class=\"climb-ticket climb-ticket-hl\">\n<p class=\"climb-sticker climb-sticker-pin\">Climb27</p>\n<p class=\"climb-ticket-kicker climb-live\">Your pass</p>\n<h2 class=\"climb-ticket-name\">Two-day ticket</h2>\n<ul>\n<li>Both days, every stage and session</li>\n<li>The grand opening and the after parties</li>\n<li>The ClimbGroup Event App to book meetings</li>\n</ul>\n<a class=\"btn btn-primary btn-lg\" href=\"#\">Get your ticket</a>\n</div></div></div></div></section><section class=\"s_climb_kit climb-p4 climb-glow pt48 pb48\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-6\"><div class=\"climb-ticket\">\n<p class=\"climb-sticker climb-sticker-pin\">Climb27</p>\n<p class=\"climb-ticket-kicker\">Partner with ClimbUK</p>\n<h3>Packages built to fit</h3>\n<ul class=\"climb-levels\">\n<li><span>Session</span><span class=\"climb-levels-note\">2 passes</span></li>\n<li><span>Stage</span><span class=\"climb-levels-note\">5 passes</span></li>\n<li><span>Digital</span><span class=\"climb-levels-note\">5 passes</span></li>\n<li><span>Headline</span><span class=\"climb-levels-note\">10 passes</span></li>\n</ul>\n<a class=\"btn btn-primary\" href=\"#\">Book a call with partnerships</a>\n</div></div></div></div></section></div>",["Selling", "The glass ticket with stub notches, highlighted and on orange", "Ticket card"]);
C["OfferCards"]=make("<section class=\"s_climb_kit climb-p5 pt48 pb48 \" data-climb-theme=\"alt\"><div class=\"container\"><ul class=\"climb-offers\">\n<li class=\"climb-offer is-soldout\">\n<p class=\"climb-offer-kicker\">Sold out</p>\n<h3 class=\"climb-offer-name\">Super Early Bird</h3>\n<p class=\"climb-price\">\u00a3120<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">The first release of standard two-day tickets. It went first.</p>\n<span aria-disabled=\"true\" class=\"btn btn-outline-secondary disabled\">Sold out</span>\n</li>\n<li class=\"climb-offer climb-offer-hl\">\n<p class=\"climb-offer-kicker\">For you</p>\n<h3 class=\"climb-offer-name\">Standard two-day</h3>\n<p class=\"climb-price\">\u00a3175<small>inc VAT</small></p>\n<p class=\"climb-was\">Full price <s>\u00a3480</s></p>\n<p class=\"climb-remaining\">199 left at this price</p>\n<p class=\"climb-offer-text\">Both days, every session, the grand opening and the after parties.</p>\n<a class=\"btn btn-primary\" href=\"#\">Get standard ticket</a>\n</li>\n<li class=\"climb-offer\">\n<h3 class=\"climb-offer-name\">One-day</h3>\n<p class=\"climb-price\">\u00a3252<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">One full day of sessions and meetings. Choose your day when you buy.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Get one-day ticket</a>\n</li>\n<li class=\"climb-offer\">\n<h3 class=\"climb-offer-name\">VIP</h3>\n<p class=\"climb-price\">\u00a3360<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">Both days plus the VIP drinks reception and the ClimbAwards.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Get VIP ticket</a>\n</li>\n</ul></div></section>",["Selling", "Ticket offers: the pick, the rest, and a closed release", "Offer cards"]);
C["ReleaseLadder"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"climb-ladder\">\n<h2 class=\"climb-visually-hidden\" id=\"climb-ticket-ladder-title\">How the standard ticket price steps up</h2>\n<p class=\"climb-eyebrow\">Release pricing</p>\n<p class=\"climb-ladder-title\">Each release closes when its tickets go, and the price steps up. Buy in the release that is open now.</p>\n<ol class=\"climb-ladder-list\">\n<li class=\"climb-ladder-step is-past\" style=\"--climb-step: 1;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Super Early Bird</span>\n<span class=\"climb-ladder-price\">\u00a3120</span>\n<span class=\"climb-ladder-share\">About 5% of tickets</span>\n<span class=\"climb-ladder-state\">Closed</span>\n</li>\n<li class=\"climb-ladder-step is-current\" style=\"--climb-step: 2;\">\n<span class=\"climb-ladder-left\">199 left at this price</span>\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Early Adopter</span>\n<span class=\"climb-ladder-price\">\u00a3175</span>\n<span class=\"climb-ladder-share\">About 10% of tickets</span>\n<span class=\"climb-ladder-state\">Open now</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 3;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">First Release</span>\n<span class=\"climb-ladder-price\">\u00a3239</span>\n<span class=\"climb-ladder-share\">About 15% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 4;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Second Release</span>\n<span class=\"climb-ladder-price\">\u00a3300</span>\n<span class=\"climb-ladder-share\">About 20% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 5;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Penultimate Release</span>\n<span class=\"climb-ladder-price\">\u00a3360</span>\n<span class=\"climb-ladder-share\">About 25% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 6;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Full price</span>\n<span class=\"climb-ladder-price\">\u00a3480</span>\n<span class=\"climb-ladder-share\">Everything else</span>\n<span class=\"climb-ladder-state\">Final</span>\n</li>\n</ol>\n</div></div></section>",["Selling", "Price releases as rising steps: past, now and next", "Release ladder"]);
C["StandCards"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><ul class=\"climb-offers climb-offers-3\">\n<li class=\"climb-offer climb-stand climb-offer-hl\">\n<p class=\"climb-left\">59 left</p>\n<span aria-hidden=\"true\" class=\"climb-plan climb-plan-4\"><i></i><i></i><i></i><i></i></span>\n<h3 class=\"climb-offer-name\">Sales Space</h3>\n<p class=\"climb-stand-size\">2m x 2m, 4 m\u00b2</p>\n<p class=\"climb-price\">\u00a34,000<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">Big enough to make noise. Room to pitch, demo and deal.</p>\n<a class=\"btn btn-primary\" href=\"#\">Book this stand<span class=\"climb-visually-hidden\">: Sales Space</span></a>\n</li>\n<li class=\"climb-offer climb-stand\">\n<p class=\"climb-left\">9 left</p>\n<span aria-hidden=\"true\" class=\"climb-plan climb-plan-2\"><i></i><i></i><i></i><i></i></span>\n<h3 class=\"climb-offer-name\">Starter Pod</h3>\n<p class=\"climb-stand-size\">Pod</p>\n<p class=\"climb-price\">\u00a31,000<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">The smallest footprint on the floor: a pod to meet from, with the same reach.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Book this stand<span class=\"climb-visually-hidden\">: Starter Pod</span></a>\n</li>\n<li class=\"climb-offer climb-stand\">\n<p class=\"climb-left\">2 left</p>\n<span aria-hidden=\"true\" class=\"climb-plan climb-plan-1\"><i></i><i></i><i></i><i></i></span>\n<h3 class=\"climb-offer-name\">Display Space</h3>\n<p class=\"climb-stand-size\">Display</p>\n<p class=\"climb-price\">\u00a32,000<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">A display footprint for a product that speaks for itself.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Book this stand<span class=\"climb-visually-hidden\">: Display Space</span></a>\n</li>\n</ul></div></section>",["Selling", "Exhibition stands with an outlined floor plan and stock", "Stand cards"]);
C["GroupOffer"]=make("<section class=\"s_climb_kit climb-p5 pt48 pb48 \" data-climb-theme=\"alt\"><div class=\"container\"><div class=\"climb-team\">\n<div>\n<p class=\"climb-team-lead\">Bringing a team?</p>\n<p>Buy four or more standard two-day tickets together and 10% comes off.</p>\n</div>\n<a class=\"btn btn-primary\" href=\"#\">Buy four or more</a>\n</div></div></section>",["Selling", "The orange band for teams and groups", "Group offer"]);
C["MomentCard"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"row g-4\">\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"A brass band playing on the main stage\" src=\"/_blob/269a6ff050ff9d750893304b9dd4ea97\"/>\n<h3>The grand opening</h3>\n<p>Day one opens on the main stage with a live performance and the headline partner announcements. Nobody is late for this one.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"ClimbAwards trophies lined up on a table\" src=\"/_blob/21b03a0002a2c39302048e2b30006184\"/>\n<h3>The ClimbAwards</h3>\n<p>One room, the businesses of the year and the people who back them, inside the VIP drinks reception.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"Glasses being filled at the drinks reception\" src=\"/_blob/1139f54015bcf7147483baf94d54cf27\"/>\n<h3>After parties</h3>\n<p>Day two wraps up with the after parties, where the deals of the day get agreed.</p>\n</div>\n</div>\n</div></div></section>",["Cards", "Photo cards for the big moments", "Moment card"]);
C["AudienceCard"]=make("<section class=\"s_climb_kit climb-p5 pt48 pb48 \" data-climb-theme=\"alt\"><div class=\"container\"><div class=\"row g-4\">\n<div class=\"col-md-6 col-lg-3\">\n<div class=\"climb-audience\">\n<img alt=\"Busy stands on the expo floor\" src=\"/_blob/fde5610ab7e0a17641420f2a30803912\"/>\n<h3>Scaling companies</h3>\n<p>Scale with the right people in the room.</p>\n<a class=\"stretched-link\" href=\"#\">See what you get<span class=\"climb-visually-hidden\"> for scaling companies</span></a>\n</div>\n</div>\n<div class=\"col-md-6 col-lg-3\">\n<div class=\"climb-audience\">\n<img alt=\"A founder talking with an investor across a table\" src=\"/_blob/8dad4479fbd704865e02a3e5945b7383\"/>\n<h3>Founders raising</h3>\n<p>Find investors looking for real deal flow.</p>\n<a class=\"stretched-link\" href=\"#\">See what you get<span class=\"climb-visually-hidden\"> for founders raising</span></a>\n</div>\n</div>\n<div class=\"col-md-6 col-lg-3\">\n<div class=\"climb-audience\">\n<img alt=\"Investors in conversation with founders\" src=\"/_blob/ffc57e42ed92e97f91dddff0e29574b9\"/>\n<h3>Investors</h3>\n<p>Deal flow you can filter. Founders you choose.</p>\n<a class=\"stretched-link\" href=\"#\">See what you get<span class=\"climb-visually-hidden\"> for investors</span></a>\n</div>\n</div>\n<div class=\"col-md-6 col-lg-3\">\n<div class=\"climb-audience\">\n<img alt=\"An adviser speaking on a panel\" src=\"/_blob/4ea29868d442b924e65ea2f3bf887582\"/>\n<h3>Professional services</h3>\n<p>Your expertise, in front of the businesses that buy it.</p>\n<a class=\"stretched-link\" href=\"#\">See what you get<span class=\"climb-visually-hidden\"> for professional services</span></a>\n</div>\n</div>\n</div></div></section>",["Cards", "Photo cards that route each audience to its page", "Audience card"]);
C["Quote"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"row g-4 pt48\">\n<div class=\"col-lg-6\">\n<blockquote class=\"climb-quote\">\n<p class=\"climb-quote-text\">It was so nice to be part of an event that really champions growing businesses in the UK and I've met some fantastic people this week who I hope to stay connected with.</p>\n<p class=\"climb-quote-by\"><strong>Rachel Kelly</strong>Partnership Manager, Caspian Insurance</p>\n</blockquote>\n</div>\n<div class=\"col-lg-6\">\n<blockquote class=\"climb-quote\">\n<p class=\"climb-quote-text\">Wins on stage are great. But the friendships, the collaborations and the momentum you build alongside them? That's the real prize.</p>\n<p class=\"climb-quote-by\"><strong>Hamzah Syed</strong>CEO and Founder, picknmixAI</p>\n</blockquote>\n</div>\n</div></div></section>",["Cards", "Testimonials from named, real people", "Quote"]);
C["Lineup"]=make("<section class=\"s_climb_kit climb-p3 pt48 pb48 \" data-climb-theme=\"ground\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-8\"><div class=\"col-lg-6 climb-lineup\">\n<p class=\"climb-lineup-kicker\">Previous speakers include</p>\n<p class=\"climb-lineup-1\">Dame Laura Kenny<b>/</b>Richard Harpin<b>/</b>Tessa Sanderson<b>/</b>Jonny Peacock</p>\n<p class=\"climb-lineup-2\">Jez Willis<b>/</b>Steve Edge<b>/</b>Fatima Khan-Shah<b>/</b>Tracy Brabin<b>/</b>Volker Hirsch<b>/</b>Kruise Leeming</p>\n<p class=\"climb-lineup-3\">Andy Wood<b>/</b>Jeff Cohen<b>/</b>Justina Williams<b>/</b>Simon Bax<b>/</b>Louis Taylor<b>/</b>Rita Collins<b>/</b>Gary Crotaz<b>/</b>Damia Mohammed<b>/</b>Janine Smith<b>/</b>Nikita Thakrar<b>/</b>Deborah Okenla<b>/</b>Sharon Fuller</p>\n</div></div></div></div></section>",["Cards", "A festival poster lineup of names in three sizes", "Lineup"]);
C["PhotoFade"]=make("<div><section aria-labelledby=\"climb-band-title\" class=\"s_climb_band climb-glow climb-p3 climb-photo-bg climb-photo-center pt96 pb96\" style=\"background-image: url('/_blob/41af7bf4b05557125367c52e1ed15799'); background-position: 50% 40%;\">\n<div class=\"climb-fade\" style=\"background-image: linear-gradient(90deg, rgba(30, 15, 5, 0.9) 0%, rgba(30, 15, 5, 0.6) 55%, rgba(30, 15, 5, 0.45) 100%), linear-gradient(180deg, rgba(30, 15, 5, 0.5) 0%, rgba(30, 15, 5, 0.2) 50%, rgb(30, 15, 5) 100%);\"></div>\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-10\">\n<h2 class=\"climb-statement climb-ruled\" id=\"climb-band-title\"><span class=\"climb-accent\">Business</span> with a <em>party</em>. Not a <span class=\"climb-accent\">party</span> for <em>business</em>.</h2>\n<p class=\"climb-band-sub\">The festival came second. ClimbUK grew out of events where founders and investors met because they had business to do. The deals, the introductions and the advice come first; the opening, the ClimbAwards and the after parties exist because business gets done faster between people who have enjoyed each other's company.</p>\n</div>\n</div>\n<div class=\"row g-4 climb-band-cards\">\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"A brass band playing on the main stage\" src=\"/_blob/269a6ff050ff9d750893304b9dd4ea97\"/>\n<h3>The grand opening</h3>\n<p>A live performance on the main stage opens day one.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"Founders and investors talking across a table\" src=\"/_blob/8dad4479fbd704865e02a3e5945b7383\"/>\n<h3>Investor Speed Networking</h3>\n<p>Short, timed meetings with investors from your industry.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"Glasses being filled at the drinks reception\" src=\"/_blob/1139f54015bcf7147483baf94d54cf27\"/>\n<h3>After parties</h3>\n<p>Day two wraps up where the deals of the day get agreed.</p>\n</div>\n</div>\n</div>\n</div>\n</section><section aria-labelledby=\"climb-band-heat-title\" class=\"s_climb_band climb-glow climb-p3 climb-photo-bg climb-photo-center pt128 pb128\" style=\"background-image: url('/_blob/fde5610ab7e0a17641420f2a30803912'); background-position: 50% 50%;\">\n<div class=\"climb-fade\" style=\"background-image: linear-gradient(90deg, rgba(30, 15, 5, 0.92) 0%, rgba(30, 15, 5, 0.7) 45%, rgba(232, 113, 42, 0.35) 100%), radial-gradient(60rem 30rem at 85% 110%, rgba(232, 113, 42, 0.55), transparent 60%), linear-gradient(180deg, rgba(30, 15, 5, 0.35) 0%, rgba(30, 15, 5, 0) 45%, rgba(30, 15, 5, 0.7) 100%);\"></div>\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-8\">\n<p class=\"climb-eyebrow\">Climb27 / Day two</p>\n<h2 class=\"climb-statement climb-ruled\" id=\"climb-band-heat-title\">The deals happen <em>after</em> the <span class=\"climb-accent\">main stage</span>.</h2>\n<p class=\"climb-band-sub\">Roundtables, Investor Speed Networking, Busk Your Business and the expo floor, all on one ticket.</p>\n<p class=\"climb-ctas pt24\">\n<a class=\"btn btn-primary btn-lg\" href=\"#\">Get standard ticket</a>\n<a class=\"btn btn-outline-secondary btn-lg\" href=\"#\">Add Speed Networking</a>\n</p>\n</div>\n</div>\n</div>\n</section><section aria-labelledby=\"climb-band-orange-title\" class=\"s_climb_band climb-glow climb-p4 climb-photo-bg climb-photo-center pt96 pb96\" style=\"background-image: url('/_blob/21b03a0002a2c39302048e2b30006184'); background-position: 50% 50%;\">\n<div class=\"climb-fade\" style=\"background-image: linear-gradient(90deg, rgba(232, 113, 42, 0.97) 0%, rgba(232, 113, 42, 0.9) 50%, rgba(232, 113, 42, 0.5) 100%), radial-gradient(40rem 20rem at 10% 0%, rgba(255, 255, 255, 0.2), transparent 60%);\"></div>\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-7\">\n<h2 class=\"climb-statement\" id=\"climb-band-orange-title\">Bring the <em>team</em>. Split the <span class=\"climb-accent\">bill</span>.</h2>\n<p class=\"lead climb-lead\">Buy four or more standard two-day tickets together and 10% comes off.</p>\n<p class=\"climb-ctas pt16\">\n<a class=\"btn btn-primary btn-lg\" href=\"#\">Buy four or more</a>\n</p>\n</div>\n</div>\n</div>\n</section></div>",["Sections", "Brown, Heat and Orange fades over Climb26 photos", "Photo fade"]);
C["Hero"]=make("<section aria-labelledby=\"climb-hero-title\" class=\"s_climb_hero climb-glow climb-p3 climb-photo-bg climb-photo-center pt128 pb128\" style=\"background-image: url('/_blob/529159adda181a39f172b015431c5578'); background-position: 70% 30%;\">\n<div class=\"climb-fade\" style=\"background-image: linear-gradient(100deg, rgba(30, 15, 5, 0.95) 0%, rgba(30, 15, 5, 0.7) 48%, rgba(30, 15, 5, 0.2) 100%);\"></div>\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-9\">\n<p class=\"climb-eyebrow\">Climb27 / The Festival for Business Growth</p>\n<h1 class=\"climb-display\" id=\"climb-hero-title\">30 June &amp; 1 July <span class=\"climb-accent\">2027</span></h1>\n<p class=\"lead climb-lead\">Founders, investors, advisers, universities and councils, in one festival for two days. Main stage, roundtables, Investor Speed Networking, the ClimbAwards and the after parties.</p>\n<p class=\"climb-ctas\">\n<a class=\"btn btn-primary btn-lg\" href=\"#\">Get your ticket</a>\n<a class=\"btn btn-outline-secondary btn-lg\" href=\"#\">Partner with ClimbUK</a>\n</p>\n<p class=\"climb-pull text-start\"><a href=\"#\">Not sure which Climb27 is yours? Pick your route</a></p>\n</div>\n</div>\n</div>\n</section>",["Sections", "Full-bleed stage photo with the poster line", "Hero"]);
C["HeroWithTicket"]=make("<section aria-labelledby=\"climb-hero-ticket-title\" class=\"s_climb_hero s_climb_hero_ticket climb-glow climb-p3 climb-photo-bg climb-photo-center pt128 pb128\" style=\"background-image: url('/_blob/269a6ff050ff9d750893304b9dd4ea97'); background-position: 60% 35%;\">\n<div class=\"climb-fade\" style=\"background-image: linear-gradient(100deg, rgba(30, 15, 5, 0.95) 0%, rgba(30, 15, 5, 0.75) 50%, rgba(30, 15, 5, 0.35) 100%);\"></div>\n<div class=\"container\">\n<div class=\"row align-items-center\">\n<div class=\"col-lg-7\">\n<p class=\"climb-eyebrow\">Climb27 / 30 June &amp; 1 July 2027</p>\n<h1 class=\"climb-display\" id=\"climb-hero-ticket-title\">Your business. Bigger <span class=\"climb-accent\"><em>stage</em></span>.</h1>\n<p class=\"lead climb-lead\">Two days of main stage moments, close conversations and after parties, with the people who can move your business on.</p>\n</div>\n<div class=\"col-lg-5\">\n<div class=\"climb-ticket climb-ticket-hl\">\n<p class=\"climb-sticker climb-sticker-pin\">Climb27</p>\n<p class=\"climb-ticket-kicker climb-live\">Your pass</p>\n<h2 class=\"climb-ticket-name\">Two-day ticket</h2>\n<ul>\n<li>Both days, every stage and session</li>\n<li>The grand opening and the after parties</li>\n<li>The ClimbGroup Event App to book meetings</li>\n</ul>\n<a class=\"btn btn-primary btn-lg\" href=\"#\">Get your ticket</a>\n</div>\n</div>\n</div>\n</div>\n</section>",["Sections", "The hero with a glass ticket to pick up", "Hero with ticket"]);
C["Moments"]=make("<section aria-labelledby=\"climb-moments-title\" class=\"s_climb_moments climb-glow climb-p3 pt112 pb112\" data-climb-theme=\"ground\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-10\">\n<h2 class=\"climb-statement climb-ruled\" id=\"climb-moments-title\">Not a <em>conference</em>. A <span class=\"climb-accent\">festival</span> for business growth.</h2>\n<p class=\"lead climb-lead\">Day one opens with a live performance on the main stage and ends with the ClimbAwards at the VIP drinks reception. Day two is roundtables, Investor Speed Networking, Busk Your Business and the after parties.</p>\n</div>\n</div>\n<div class=\"row g-4\">\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"A brass band playing on the main stage\" src=\"/_blob/269a6ff050ff9d750893304b9dd4ea97\"/>\n<h3>The grand opening</h3>\n<p>Day one opens on the main stage with a live performance and the headline partner announcements. Nobody is late for this one.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"ClimbAwards trophies lined up on a table\" src=\"/_blob/21b03a0002a2c39302048e2b30006184\"/>\n<h3>The ClimbAwards</h3>\n<p>One room, the businesses of the year and the people who back them, inside the VIP drinks reception.</p>\n</div>\n</div>\n<div class=\"col-md-4\">\n<div class=\"climb-moment\">\n<img alt=\"Glasses being filled at the drinks reception\" src=\"/_blob/1139f54015bcf7147483baf94d54cf27\"/>\n<h3>After parties</h3>\n<p>Day two wraps up with the after parties, where the deals of the day get agreed.</p>\n</div>\n</div>\n</div>\n<div class=\"row\">\n<div class=\"col-12 pt48\">\n<p class=\"climb-ctas\">\n<a class=\"btn btn-primary\" href=\"#\">Get VIP ticket</a>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Standard ticket</a>\n</p>\n<p class=\"climb-pull\"><a href=\"#\">This is what it looked like last time</a></p>\n</div>\n</div>\n</div>\n</section>",["Sections", "Statement, lead and three moment cards", "Moments"]);
C["PhotoWall"]=make("<section aria-labelledby=\"climb-photo-wall-title\" class=\"s_climb_photo_wall climb-p1 pt96 pb96\" data-climb-theme=\"ground\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-8 pb32\">\n<p class=\"climb-eyebrow\">Climb26</p>\n<h2 class=\"climb-statement\" id=\"climb-photo-wall-title\">Find your <span class=\"climb-accent\"><em>moment</em></span></h2>\n<p class=\"lead climb-lead mb-0\">The photo wall, the playlist and what people said afterwards. Tagged yourself? Find your moment.</p>\n</div>\n</div>\n<div class=\"climb-mosaic\">\n<figure class=\"climb-mosaic-feature\">\n<img alt=\"A giant ClimbUK deckchair outside the festival\" src=\"/_blob/a56691b6d62c3f1f4f010ebb616db020\"/>\n<figcaption>Watch the Climb26 playlist</figcaption>\n<p class=\"climb-sticker climb-sticker-pin\">#ClimbUK</p>\n</figure>\n<img alt=\"Four of the ClimbUK team outside the entrance under the Welcome to ClimbUK banner\" src=\"/_blob/387a06e556425ade92b9b62b2e6d1829\"/>\n<img alt=\"A delegate in an orange lanyard laughing during a table conversation\" src=\"/_blob/a510de8310ca9e9cfc799181e191495e\"/>\n<img alt=\"A young reporter with an orange microphone, smiling between interviews\" src=\"/_blob/4376f689e86598dc38bff0da22a60862\"/>\n<img alt=\"A ClimbUK crew member in an orange T-shirt waving across the floor\" src=\"/_blob/38a3601ab764efaee86705732ae9e21a\"/>\n<img alt=\"Three delegates laughing together on the expo floor\" src=\"/_blob/c4691eb46e406e937f84ee0a7eae06e1\"/>\n<img alt=\"A delegate trying a virtual reality headset at a stand\" src=\"/_blob/c416d3d9184e018f1bb4d613da3fe316\"/>\n<img alt=\"Two delegates testing virtual reality headsets on a stand\" src=\"/_blob/e4c1d6fc6d80028ec5a18930bee44998\"/>\n<img alt=\"A stand team holding a giant pink megaphone sign about amplifying women in tech\" src=\"/_blob/392ec3103c422e888e92c81a2e647be6\"/>\n</div>\n<div class=\"row g-4 pt48\">\n<div class=\"col-lg-6\">\n<blockquote class=\"climb-quote\">\n<p class=\"climb-quote-text\">It was so nice to be part of an event that really champions growing businesses in the UK and I've met some fantastic people this week who I hope to stay connected with.</p>\n<p class=\"climb-quote-by\"><strong>Rachel Kelly</strong>Partnership Manager, Caspian Insurance</p>\n</blockquote>\n</div>\n<div class=\"col-lg-6\">\n<blockquote class=\"climb-quote\">\n<p class=\"climb-quote-text\">Wins on stage are great. But the friendships, the collaborations and the momentum you build alongside them? That's the real prize.</p>\n<p class=\"climb-quote-by\"><strong>Hamzah Syed</strong>CEO and Founder, picknmixAI</p>\n</blockquote>\n</div>\n</div>\n<div class=\"row\">\n<div class=\"col-12 pt40\">\n<p class=\"climb-ctas\">\n<a class=\"btn btn-primary\" href=\"#\">Find your Climb26 moment</a>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Open the photo gallery</a>\n</p>\n<p class=\"climb-pull\"><a href=\"#\">Want your name on that wall? Partner, exhibit or speak</a></p>\n</div>\n</div>\n</div>\n</section>",["Sections", "A mosaic of Climb26 photos and two quotes", "Photo wall"]);
C["TicketBand"]=make("<section aria-labelledby=\"climb-ticket-band-title\" class=\"s_climb_ticket_band climb-glow climb-p4 pt96 pb96\">\n<div class=\"container\">\n<div class=\"row align-items-center\">\n<div class=\"col-lg-7\">\n<h2 class=\"climb-statement\" id=\"climb-ticket-band-title\">Partner with ClimbUK. <em>Meet</em> the right people.</h2>\n<p class=\"climb-lead\">Delegate passes, a stage and a prime stand, in front of the businesses that buy what you do.</p>\n<p class=\"climb-ctas\">\n<a class=\"btn btn-primary btn-lg\" href=\"#\">See the partnership packages</a>\n</p>\n</div>\n<div class=\"col-lg-5\">\n<div class=\"climb-ticket\">\n<p class=\"climb-sticker climb-sticker-pin\">Climb27</p>\n<p class=\"climb-ticket-kicker\">Partner with ClimbUK</p>\n<h3>Packages built to fit</h3>\n<ul class=\"climb-levels\">\n<li><span>Session</span><span class=\"climb-levels-note\">2 passes</span></li>\n<li><span>Stage</span><span class=\"climb-levels-note\">5 passes</span></li>\n<li><span>Digital</span><span class=\"climb-levels-note\">5 passes</span></li>\n<li><span>Headline</span><span class=\"climb-levels-note\">10 passes</span></li>\n</ul>\n<a class=\"btn btn-primary\" href=\"#\">Book a call with partnerships</a>\n</div>\n</div>\n</div>\n</div>\n</section>",["Sections", "Climb Orange band with a Dark Brown ticket", "Ticket band"]);
C["Tickets"]=make("<section aria-labelledby=\"climb-tickets-title\" class=\"s_climb_tickets climb-p5 pt96 pb96\" data-climb-theme=\"alt\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"col-lg-8 pb48\">\n<h2 class=\"climb-statement climb-ruled\" id=\"climb-tickets-title\">Pick your <span class=\"climb-accent\">ticket</span></h2>\n<p class=\"lead climb-lead mb-0\">30 June and 1 July 2027. Today's price is the lowest it will be: the standard ticket rises with every release.</p>\n</div>\n</div>\n<ul class=\"climb-offers\">\n<li class=\"climb-offer is-soldout\">\n<p class=\"climb-offer-kicker\">Sold out</p>\n<h3 class=\"climb-offer-name\">Super Early Bird</h3>\n<p class=\"climb-price\">\u00a3120<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">The first release of standard two-day tickets. It went first.</p>\n<span aria-disabled=\"true\" class=\"btn btn-outline-secondary disabled\">Sold out</span>\n</li>\n<li class=\"climb-offer climb-offer-hl\">\n<p class=\"climb-offer-kicker\">For you</p>\n<h3 class=\"climb-offer-name\">Standard two-day</h3>\n<p class=\"climb-price\">\u00a3175<small>inc VAT</small></p>\n<p class=\"climb-was\">Full price <s>\u00a3480</s></p>\n<p class=\"climb-remaining\">199 left at this price</p>\n<p class=\"climb-offer-text\">Both days, every session, the grand opening and the after parties.</p>\n<a class=\"btn btn-primary\" href=\"#\">Get standard ticket</a>\n</li>\n<li class=\"climb-offer\">\n<h3 class=\"climb-offer-name\">One-day</h3>\n<p class=\"climb-price\">\u00a3252<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">One full day of sessions and meetings. Choose your day when you buy.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Get one-day ticket</a>\n</li>\n<li class=\"climb-offer\">\n<h3 class=\"climb-offer-name\">VIP</h3>\n<p class=\"climb-price\">\u00a3360<small>inc VAT</small></p>\n<p class=\"climb-offer-text\">Both days plus the VIP drinks reception and the ClimbAwards.</p>\n<a class=\"btn btn-outline-secondary\" href=\"#\">Get VIP ticket</a>\n</li>\n</ul>\n<div class=\"pt48\">\n<div class=\"climb-ladder\">\n<h3 class=\"climb-visually-hidden\">How the standard ticket price steps up</h3>\n<p class=\"climb-eyebrow\">Release pricing</p>\n<p class=\"climb-ladder-title\">Each release closes when its tickets go, and the price steps up. Buy in the release that is open now.</p>\n<ol class=\"climb-ladder-list\">\n<li class=\"climb-ladder-step is-past\" style=\"--climb-step: 1;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Super Early Bird</span>\n<span class=\"climb-ladder-price\">\u00a3120</span>\n<span class=\"climb-ladder-share\">About 5% of tickets</span>\n<span class=\"climb-ladder-state\">Closed</span>\n</li>\n<li class=\"climb-ladder-step is-current\" style=\"--climb-step: 2;\">\n<span class=\"climb-ladder-left\">199 left at this price</span>\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Early Adopter</span>\n<span class=\"climb-ladder-price\">\u00a3175</span>\n<span class=\"climb-ladder-share\">About 10% of tickets</span>\n<span class=\"climb-ladder-state\">Open now</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 3;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">First Release</span>\n<span class=\"climb-ladder-price\">\u00a3239</span>\n<span class=\"climb-ladder-share\">About 15% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 4;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Second Release</span>\n<span class=\"climb-ladder-price\">\u00a3300</span>\n<span class=\"climb-ladder-share\">About 20% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 5;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Penultimate Release</span>\n<span class=\"climb-ladder-price\">\u00a3360</span>\n<span class=\"climb-ladder-share\">About 25% of tickets</span>\n<span class=\"climb-ladder-state\">Next</span>\n</li>\n<li class=\"climb-ladder-step is-next\" style=\"--climb-step: 6;\">\n<span aria-hidden=\"true\" class=\"climb-ladder-cap\"></span>\n<span aria-hidden=\"true\" class=\"climb-ladder-dot\"></span>\n<span class=\"climb-ladder-name\">Full price</span>\n<span class=\"climb-ladder-price\">\u00a3480</span>\n<span class=\"climb-ladder-share\">Everything else</span>\n<span class=\"climb-ladder-state\">Final</span>\n</li>\n</ol>\n</div>\n</div>\n<div class=\"climb-team\">\n<div>\n<p class=\"climb-team-lead\">Bringing a team?</p>\n<p>Buy four or more standard two-day tickets together and 10% comes off.</p>\n</div>\n<a class=\"btn btn-primary\" href=\"#\">Buy four or more</a>\n</div>\n<p class=\"climb-pull pt32\"><a href=\"#\">Bigger group, a stand or a stage? Book a call</a></p>\n</div>\n</section>",["Sections", "Offers, the release ladder, the group offer and the pull link", "Tickets"]);
