C["EmailSignature"]=make("<section class=\"s_climb_kit climb-p5 pt32 pb32\" data-climb-theme=\"sig\"><div class=\"container\"><div class=\"climb-sig\"><p>Kind regards,</p><div class=\"climb-sig-top\"><div><p class=\"climb-sig-name\">Alex Morgan</p><p>Partnerships Lead</p><p><a href=\"#\">Book a meeting with me</a></p><p><b>T:</b> 0300 123 4567 &nbsp; <b>M:</b> 07700 900123</p><p><a href=\"#\">alex.morgan@climb-uk.com</a> | <a href=\"#\">climb-uk.com</a></p></div><div class=\"climb-sig-brand\"><img class=\"climb-on-dark\" src=\"/_blob/5efde3237cf074853d62dfec86e7584b\" alt=\"ClimbUK\"><img class=\"climb-on-light\" src=\"/_blob/892ab1994f4d217239925ae8ef695458\" alt=\"ClimbUK\"><div class=\"climb-sig-icons\"><a href=\"#\" aria-label=\"ClimbUK on Facebook\"><img src=\"/_blob/04b293f3e97ff2f5994dc3bb0b749b8d\" width=\"24\" height=\"24\" alt=\"\"></a><a href=\"#\" aria-label=\"ClimbUK on X\"><img src=\"/_blob/3f8a39777032b20f88273a73687544ab\" width=\"24\" height=\"24\" alt=\"\"></a><a href=\"#\" aria-label=\"ClimbUK on Bluesky\"><img src=\"/_blob/bb6024ef11b54934d7ed091abb435608\" width=\"24\" height=\"24\" alt=\"\"></a><a href=\"#\" aria-label=\"ClimbUK on Instagram\"><img src=\"/_blob/435c516c9801b76310550c361b9cbd39\" width=\"24\" height=\"24\" alt=\"\"></a><a href=\"#\" aria-label=\"ClimbUK on LinkedIn\"><img src=\"/_blob/8566d575bcc4ed9300fc7789c404fc6e\" width=\"24\" height=\"24\" alt=\"\"></a></div></div></div><p class=\"climb-sig-note\">To help us respond quickly, non-sales enquiries go through our <a href=\"#\">Helpdesk</a> before email. For partnerships, email <a href=\"#\">partners@climb-uk.com</a>; for exhibiting, <a href=\"#\">exhibitors@climb-uk.com</a>.</p><a href=\"#\"><img class=\"climb-sig-banner\" src=\"/_blob/692409d22e1a773f744cbca56b8c22c9\" width=\"720\" alt=\"Climb27. Your business. Bigger stage. Get your ticket.\"></a><p class=\"climb-sig-legal\">This email and any attachments are confidential and meant only for the person they are addressed to. If it reached you by mistake, please tell the sender and delete it.</p></div></div></section>",["Brand", "The full signature block: contact, logo and icons, notice, photo banner, legal line", "Email signature"]);
